--
-- Table structure for table `FactSales`
--

DROP TABLE IF EXISTS `FactSales`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `FactSales` (
  `SalesKey` int NOT NULL,
  `OrderID` varchar(30) NOT NULL,
  `ProductID` varchar(30) NOT NULL,
  `CustomerID` varchar(20) NOT NULL,
  `Sales` decimal(15,4) NOT NULL,
  `Quantity` int NOT NULL,
  `Discount` decimal(8,4) NOT NULL DEFAULT '0.0000',
  `Profit` decimal(15,4) NOT NULL,
  `ShippingCost` decimal(15,4) NOT NULL,
  `OrderDate` datetime NOT NULL,
  `ShipDate` datetime NOT NULL,
  `IsReturned` enum('Yes','No') NOT NULL DEFAULT 'No',
  `PriorityKey` int NOT NULL,
  `GeoKey` int NOT NULL,
  `ShipModeId` int NOT NULL,
  PRIMARY KEY (`SalesKey`),
  KEY `idx_order_id` (`OrderID`),
  KEY `idx_product_id` (`ProductID`),
  KEY `idx_customer_id` (`CustomerID`),
  KEY `idx_priority_key` (`PriorityKey`),
  KEY `idx_geo_key` (`GeoKey`),
  KEY `idx_ship_mode_id` (`ShipModeId`),
  CONSTRAINT `fk_sales_customer` FOREIGN KEY (`CustomerID`) REFERENCES `DimCustomer` (`CustomerID`),
  CONSTRAINT `fk_sales_geography` FOREIGN KEY (`GeoKey`) REFERENCES `DimGeography` (`GeoKey`),
  CONSTRAINT `fk_sales_order_priority` FOREIGN KEY (`PriorityKey`) REFERENCES `DimOrderPriority` (`PriorityKey`),
  CONSTRAINT `fk_sales_product` FOREIGN KEY (`ProductID`) REFERENCES `DimProduct` (`ProductID`),
  CONSTRAINT `fk_sales_ship_mode` FOREIGN KEY (`ShipModeId`) REFERENCES `DimShipMode` (`ShipModeID`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

